/**
 * The backend's country table and the Stripe catalog agree with the page's prices
 * (STRIPE_MANAGED_PAYMENTS_IMPLEMENTATION_PLAN B4).
 *
 * backend/src/config/premiumCountryPrices.json is generated by scripts/stripe/country-prices.mjs; the
 * Stripe catalog by scripts/stripe/catalog.mjs. Both come from countryPrices.js. If a price changes and
 * either is not regenerated, a buyer could be charged a price the page does not show: this fails.
 */
import { describe, expect, it } from 'vitest';
import stored from '../../../backend/src/config/premiumCountryPrices.json';
import { countryTable } from '../../../scripts/stripe/country-prices.mjs';
import { expectedPrices, lookupKeyFor } from '../../../scripts/stripe/catalog.mjs';

type Entry = { tier: 'full' | 'reduced'; currency: string; yearlyMinor: string; monthlyMinor: string | null };

describe('Stripe prices per country', () => {
  it('the backend file is what priceFor() says today (rerun country-prices.mjs --write)', () => {
    expect(stored).toEqual(countryTable());
  });

  it('every country\'s price exists in the Stripe catalog at exactly that amount', () => {
    const catalog = expectedPrices() as Record<string, { base: { currency: string; minor: string }; options: Record<string, string> }>;
    const amount = (key: string, currency: string) => {
      const price = catalog[key];
      return currency === price.base.currency ? price.base.minor : price.options[currency];
    };
    const entries: Array<[string, Entry]> = [['unknown', stored.unknown as Entry], ...Object.entries(stored.countries as Record<string, Entry>)];
    for (const [cc, e] of entries) {
      const reduced = e.tier === 'reduced';
      expect(amount(lookupKeyFor('yearly', reduced), e.currency), `${cc} yearly`).toBe(e.yearlyMinor);
      expect(amount(lookupKeyFor('oneYear', reduced), e.currency), `${cc} pass`).toBe(e.yearlyMinor);
      if (e.monthlyMinor) expect(amount(lookupKeyFor('monthly', reduced), e.currency), `${cc} monthly`).toBe(e.monthlyMinor);
      else expect(e.tier, `${cc}: only reduced-price countries have no monthly plan`).toBe('reduced');
    }
  });
});
